import{_ as t,o as a,c as s,a0 as i}from"./chunks/framework.BxCN1dRw.js";const u=JSON.parse('{"title":"Walkthrough: Title search and safe preview","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/search-preview"},"headers":[],"relativePath":"en/tutorials/search-preview.md","filePath":"en/tutorials/search-preview.md"}'),r={name:"en/tutorials/search-preview.md"};function n(o,e,d,h,l,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="walkthrough-title-search-and-safe-preview" tabindex="-1">Walkthrough: Title search and safe preview <a class="header-anchor" href="#walkthrough-title-search-and-safe-preview" aria-label="Permalink to &quot;Walkthrough: Title search and safe preview&quot;">​</a></h1><p>Run <code>just dev</code>, sign in, create a document titled &quot;部署 100%_完成&quot; and fill the body with:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 部署笔记</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**检查列表**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">：</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">x</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] 数据库可连接</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ ] 发布应用</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">参见 [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">Rust 官网</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">https://www.rust-lang.org/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)。</span></span></code></pre></div><p>Switch to &quot;Preview&quot; to see the layout, then save. The reading page shows the same safely rendered result. Return to &quot;My documents&quot; from the sidebar, type <code>100%_</code> and press Enter — the document appears; both <code>%</code> and <code>_</code> are ordinary characters here. Clearing the search restores the list. More results use &quot;Load more&quot;; changing the keyword or resubmitting restarts from the first page.</p><p>Operation names for search and preview stay consistent across Chinese and English:</p><table tabindex="0"><thead><tr><th>Page element</th><th>Chinese</th><th>English</th></tr></thead><tbody><tr><td>Search field</td><td>标题关键词</td><td>Title keywords</td></tr><tr><td>Edit tab</td><td>编辑</td><td>Edit</td></tr><tr><td>Preview tab</td><td>预览</td><td>Preview</td></tr><tr><td>Clear search</td><td>清除搜索</td><td>Clear search</td></tr><tr><td>Load more</td><td>加载更多</td><td>Load more</td></tr><tr><td>Retry pagination</td><td>重试加载更多</td><td>Retry loading more</td></tr></tbody></table><h2 id="_1-adding-a-filter-to-the-existing-list" tabindex="-1">1. Adding a filter to the existing list <a class="header-anchor" href="#_1-adding-a-filter-to-the-existing-list" aria-label="Permalink to &quot;1. Adding a filter to the existing list&quot;">​</a></h2><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/crates/app/src/modules/knowledge/mod.rs" target="_blank" rel="noreferrer">HTTP contract</a> adds an optional <code>q</code> to the existing list endpoint while still returning summaries only. The keyword is at most 200 Unicode characters and cannot contain NUL; matching is a case-insensitive title substring match after trimming both ends. An empty keyword shows every accessible document in the personal knowledge base. Create titles stay limited to 1–200 characters and bodies to 1 MiB as UTF-8; the browser gives immediate feedback and the server keeps validating independently.</p><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/crates/app/src/modules/knowledge/application.rs" target="_blank" rel="noreferrer">Application</a> escapes LIKE&#39;s <code>%</code>, <code>_</code> and backslash, then binds the pattern as an SQL parameter. Never concatenate user input into SQL, and never make <code>%</code> a wildcard the user controls.</p><p>The endpoint&#39;s scope is &quot;my personal knowledge base&quot;. A later chapter&#39;s knowledge base pages provide the knowledge-base-scoped browsing entry; Owner read permission does not mix organization-wide documents into &quot;My documents&quot; here. The permission condition, the keyword and the pagination bounds enter the query together — inaccessible titles are never fetched first and filtered in the browser.</p><h2 id="_2-cursors-bind-to-the-query-conditions" tabindex="-1">2. Cursors bind to the query conditions <a class="header-anchor" href="#_2-cursors-bind-to-the-query-conditions" aria-label="Permalink to &quot;2. Cursors bind to the query conditions&quot;">​</a></h2><p>Pagination sorts by <code>created_at DESC, id DESC</code>. Inserting new documents cannot push records that belong on the next page back onto the previous one. The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/crates/app/src/modules/knowledge/pagination.rs" target="_blank" rel="noreferrer">cursor</a> carries the current identity, scope/ordering, a digest of the normalized keyword and the last item&#39;s position; changing identity or keyword forces a fresh query. Every page re-checks the current Grant; the cursor is a position, not an authorization credential, and guarantees no cross-page database snapshot.</p><p><code>limit</code> defaults to 50, caps at 100; the server fetches one extra row to decide <code>has_more</code> and never returns totals or bodies. An invalid cursor returns a structured 400; network failures keep the request ID and the page offers re-querying or retrying the next page.</p><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/packages/views/src/knowledge/documents-view.tsx" target="_blank" rel="noreferrer">View</a> uses TanStack Query with a key covering the identity, the personal-knowledge-base scope and the keyword; saved documents still live only in the Query cache. The search input is form state and the preview shows the unsaved draft — no second resource store. Switching identity clears the cache and rebuilds the search form. The list keeps at most ten pages in memory, evicting the oldest page beyond that window; a fresh search starts over.</p><p>UI language and theme are shared preference state: switching updates copy and formatting (dates, for example) without remounting the page, and the keyword plus results stay untouched; bilingual View tests cover the representative pages in both languages.</p><h2 id="_3-treating-untrusted-markdown-as-content" tabindex="-1">3. Treating untrusted Markdown as content <a class="header-anchor" href="#_3-treating-untrusted-markdown-as-content" aria-label="Permalink to &quot;3. Treating untrusted Markdown as content&quot;">​</a></h2><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/packages/views/src/knowledge/markdown-content.tsx" target="_blank" rel="noreferrer">Markdown renderer</a> uses pinned versions of <code>react-markdown</code>, <code>remark-gfm</code> and <code>rehype-sanitize</code>:</p><ul><li><code>skipHtml</code> disables raw HTML and <code>rehype-raw</code> stays off.</li><li>The default URL protocol filtering is kept, followed by sanitizing with the default schema; filtered links render as plain text.</li><li>Headings, lists, emphasis, code, links, tables and task lists are supported.</li><li>External links open as ordinary browser links with <code>noopener noreferrer</code>; the server never fetches links.</li><li>Images currently show their alternative text without loading external images; the attachments chapter wires authorized resource references — permanently public storage URLs must never be pasted into the body.</li></ul><p>The &quot;Edit&quot; panel keeps the original input; only switching to &quot;Preview&quot; parses the body once. The parser loads on demand through a dynamic import and never loads on the register page or re-parses on every keystroke. Drafts over 1 MiB cannot preview or submit, but the input stays so the user can shrink it and retry. Adding a Markdown plugin requires re-reviewing whether it can produce unsanitized HTML/URLs.</p><h2 id="_4-verifying-from-the-public-entry" tabindex="-1">4. Verifying from the public entry <a class="header-anchor" href="#_4-verifying-from-the-public-entry" aria-label="Permalink to &quot;4. Verifying from the public entry&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> knowledge</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/knowledge.test.tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/knowledge-bilingual.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>HTTP tests use a real PostgreSQL and verify literal escaping, ordering, filter binding, input bounds, cross-account invisibility and continued pagination after revocation. View tests operate the real page, covering keyboard tab switching, safe links, draft retention, pagination failure retries, empty results and re-querying.</p><p>Run once when the key journey completes:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/e2e.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/e2e/knowledge.spec.ts</span></span></code></pre></div><p>A real Chromium registers a Member, writes with a preview, saves, refreshes, then searches by title and opens the body. Day-to-day changes run the targeted HTTP/View tests without repeating the browser journey on every push.</p><h2 id="_5-copying-the-pattern-into-your-own-business" tabindex="-1">5. Copying the pattern into your own business <a class="header-anchor" href="#_5-copying-the-pattern-into-your-own-business" aria-label="Permalink to &quot;5. Copying the pattern into your own business&quot;">​</a></h2><p>Add a bounded filter to your own list contract, parameterize the query, and put the same filter into the cursor and the Query key; authorization happens on the server. Keep content-format conversion at the business View boundary, not in the Core session or the common SDK.</p><p>This chapter&#39;s source, tests, generated Knowledge operations and tutorial belong to the knowledge example; the generic Tabs are reusable UI. The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/examples/knowledge-base/manifest.json" target="_blank" rel="noreferrer">ownership manifest</a> records the removal scope. The Markdown dependencies are used only by the example Views; the removal tool deletes that dependency registration too.</p><p>Library docs: <a href="https://github.com/remarkjs/react-markdown/tree/10.1.0#security" target="_blank" rel="noreferrer">react-markdown 10.1.0</a>, <a href="https://github.com/remarkjs/remark-gfm/tree/4.0.1" target="_blank" rel="noreferrer">remark-gfm 4.0.1</a>, <a href="https://github.com/rehypejs/rehype-sanitize/tree/6.0.0" target="_blank" rel="noreferrer">rehype-sanitize 6.0.0</a>.</p><hr><p>Source version：<code>d209def654c8</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/docs/tutorials/05-search-preview.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,31)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
